import{G as t,b as e,c as r,ae as o}from"./chunks/framework.l_MR1ur9.js";const b=JSON.parse('{"title":"ChatGPT学习","description":"","frontmatter":{"title":"ChatGPT学习","date":"2023-11-22 17:57:44","author":"花木凋零成兰","tags":["AI","ChatGPT"],"categories":["人工智能"]},"headers":[],"relativePath":"AI/ChatGPT学习.md","filePath":"AI/ChatGPT学习.md","lastUpdated":1791630580000}'),i={name:"AI/ChatGPT学习.md"};function l(n,a,h,s,p,d){return e(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1700675864000"},[...a[0]||(a[0]=[o('<h1 id="chatgpt学习" tabindex="-1">ChatGPT学习 <a class="header-anchor" href="#chatgpt学习" aria-label="Permalink to &quot;ChatGPT学习&quot;">​</a></h1><h2 id="chatgpt-介绍" tabindex="-1">ChatGPT 介绍 <a class="header-anchor" href="#chatgpt-介绍" aria-label="Permalink to &quot;ChatGPT 介绍&quot;">​</a></h2><p>ChatGPT是一款由OpenAI开发的先进人工智能助手，基于强大的GPT架构，旨在为用户提供丰富的、高质量的语言理解和生成服务。</p><h2 id="gpt-架构" tabindex="-1">GPT 架构 <a class="header-anchor" href="#gpt-架构" aria-label="Permalink to &quot;GPT 架构&quot;">​</a></h2><p>GPT 是一种自然语言处理模型。 自然语言处理模型，即可以实现人与计算机之间通过自然语言进行有效通信；自然语言俗称即为人类语言。</p><p>GPT 全称为 <strong>Generative Pre-trained Transformer</strong></p><ul><li>Generative：翻译为“生成式”，即GPT具有生成新文本能力。</li><li>Pre-trained：翻译为“预训练”，即在使用ChatGPT之前，GPT模型已经通过海量的文本数据进行了预训练，学习掌握了语言结构、语法、语义等方面知识，在处理提问时，有强大的<strong>迁移学习</strong>能力，即可以做到举一反三。</li><li>Transformer：翻译为“转换器”，这里指<strong>Transformer架构</strong>，即一种专门的深度学习架构，是专为自然语言处理任务设计的深度学习架构。</li></ul><p>GPT 也被归类到<strong>大语言模型</strong>(Large Language Model，简称<strong>LLM</strong>)中，</p><h2 id="图灵测试" tabindex="-1">图灵测试 <a class="header-anchor" href="#图灵测试" aria-label="Permalink to &quot;图灵测试&quot;">​</a></h2><p>是一种评估机器是否具有智能的方法； 基本思想是：计算机程序在与人类的自然语言对话中，让人类无法区分它与另外一位真实的人类之间的差别，那这个计算机程序就可以被认为具有智能。</p><h2 id="模型参数" tabindex="-1">模型参数 <a class="header-anchor" href="#模型参数" aria-label="Permalink to &quot;模型参数&quot;">​</a></h2><p>模型参数是指模型学习和存储知识的核心部分。</p><p>人工智能，采用的模型参数越多，输出的结果也就精准，并且模型会根据海量的数据来不断调整和优化自己的参数，这个自我优化过程就是模型的训练过程</p><h2 id="gpt-3-5" tabindex="-1">GPT 3.5 <a class="header-anchor" href="#gpt-3-5" aria-label="Permalink to &quot;GPT 3.5&quot;">​</a></h2><p>在GPT3强大的<strong>零样本学习</strong>能力的基础上，增加了<strong>代码训练</strong>和<strong>指令微调</strong>。</p><ul><li>零样本学习：即让模型在没有特定任务训练数据的情况下，通过推理完成任务。</li><li>代码训练：让GPT 3-5模型具备更好的代码生成和代码理解能力，间接拥有了使用思维链进行复杂推理的能力。</li><li>指令微调：使具备更好的模型泛化能力，同时模型的生成结果更加符合人类的预期。</li></ul><h2 id="gpt4" tabindex="-1">GPT4 <a class="header-anchor" href="#gpt4" aria-label="Permalink to &quot;GPT4&quot;">​</a></h2><ul><li>拥有比GPT 3-5多得多的模型参数，大大提升了生成文本的质量和准确。</li><li>模型架构从自然语言处理模型升级成了<strong>多模态模型</strong>。</li><li>支持更长的文字输入，最大长度：25000字。</li></ul><h3 id="多模态" tabindex="-1">多模态 <a class="header-anchor" href="#多模态" aria-label="Permalink to &quot;多模态&quot;">​</a></h3><p>是指同时处理和理解多种类型数据的技术</p><h2 id="chatgpt-的应用场景" tabindex="-1">ChatGPT 的应用场景 <a class="header-anchor" href="#chatgpt-的应用场景" aria-label="Permalink to &quot;ChatGPT 的应用场景&quot;">​</a></h2><ul><li>文案创作</li><li>语言翻译</li><li>金融分析</li><li>知识搜索</li><li>聊天工具</li><li>专业咨询</li><li>辅助编程</li><li>辅助AI绘画</li><li>等等……</li></ul><h2 id="参考学习文章" tabindex="-1">参考学习文章 <a class="header-anchor" href="#参考学习文章" aria-label="Permalink to &quot;参考学习文章&quot;">​</a></h2><p><a href="https://xiaobot.net/p/ai666" target="_blank" rel="noreferrer">每个人的AI学习手册 (xiaobot.net)</a></p><p><a href="https://xiaobot.net/post/13f443ae-67ed-4f3c-8704-77f7de95ef00" target="_blank" rel="noreferrer">第03讲：什么是ChatGPT？ (xiaobot.net)</a></p><p><a href="https://xiaobot.net/post/daf1d886-2d51-4a3b-b3c5-ba5ff02a8577" target="_blank" rel="noreferrer">第04讲：ChatGPT的发展历程 (xiaobot.net)</a></p><p><a href="https://xiaobot.net/post/4587bbec-409e-4167-b5b6-86013d350b91" target="_blank" rel="noreferrer">第05讲：GPT-4强大在哪里？ (xiaobot.net)</a></p><p><a href="https://xiaobot.net/post/5d0a677e-05bd-48fc-bf0d-df67e3002f3f" target="_blank" rel="noreferrer">第06讲：ChatGPT的应用场景 (xiaobot.net)</a></p>',28)])])}const f=t(i,[["render",l]]);export{b as __pageData,f as default};
